//! `localeCompare` vectors recorded in Chrome (`scripts/record-locale-compare.mjs`), checked
//! through `reactors`, which sorts people by name exactly as the TS does (`byName`, a stable
//! `Array.prototype.sort` with `a.localeCompare(b)`). The expected orders are the browser's —
//! the file is regenerated by the script, never edited.
use serde_json::{json, Value as Json};
use we_data::run_host_function;
use we_expr::Value;

fn vectors() -> Json {
    serde_json::from_str(include_str!("vectors/locale_compare.json")).expect("vectors parse")
}

/// The names `reactors` returns for people named `names`, in that input order.
fn sorted_by_reactors(names: &[&str]) -> Vec<String> {
    let signals: Vec<Json> = (0..names.len())
        .map(|i| json!({ "author": format!("did:{i}"), "value": 1 }))
        .collect();
    let profiles: Vec<Json> = names
        .iter()
        .enumerate()
        .map(|(i, n)| json!({ "did": format!("did:{i}"), "name": n }))
        .collect();
    let out = run_host_function(
        "reactors",
        &Value::from_json(&json!({ "signals": signals, "profiles": profiles, "me": "did:none" })),
    )
    .to_json();
    out["people"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| p["name"].as_str().unwrap().to_string())
        .collect()
}

fn strs(v: &Json) -> Vec<&str> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|s| s.as_str().unwrap())
        .collect()
}

/// Every ordered pair: a stable sort of `[a, b]` keeps it unless the browser said `a > b`.
/// With both `(a, b)` and `(b, a)` present, that pins the sign, ties included.
#[test]
fn names_compare_like_browser_locale_compare() {
    let v = vectors();
    let mut wrong = Vec::new();
    for p in v["pairs"].as_array().unwrap() {
        let (a, b) = (p["a"].as_str().unwrap(), p["b"].as_str().unwrap());
        let expected = if p["cmp"].as_i64().unwrap() > 0 {
            vec![b, a]
        } else {
            vec![a, b]
        };
        let got = sorted_by_reactors(&[a, b]);
        if got != expected {
            wrong.push(format!("{a:?} vs {b:?}: browser {}, got {got:?}", p["cmp"]));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} pairs differ:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
}

/// Whole lists, including canonically equivalent spellings in both input orders: they compare
/// equal in the browser, so the stable sort keeps whichever came first.
#[test]
fn name_lists_sort_like_the_browser() {
    let v = vectors();
    for s in v["sorts"].as_array().unwrap() {
        let input = strs(&s["input"]);
        assert_eq!(
            sorted_by_reactors(&input),
            strs(&s["sorted"]),
            "sorting {input:?}"
        );
    }
}

/// The labels of the assignment menu's first group for `members`, with `holder` (if any) on it.
fn menu_labels(names: &[&str], holder: Option<usize>) -> Vec<String> {
    let members: Vec<Json> = names
        .iter()
        .enumerate()
        .map(|(i, n)| json!({ "did": format!("did:{i}"), "name": n }))
        .collect();
    let rows: Vec<Json> = holder
        .map(|i| json!({ "node": "n1", "agent": format!("did:{i}"), "kind": "helper" }))
        .into_iter()
        .collect();
    let menu = run_host_function(
        "involvementMenu",
        &Value::from_json(&json!({
            "node": "n1",
            "entity": "TaskBlock",
            "rows": rows,
            "types": [{ "slug": "helper", "semantic": "responsible", "reflexive": false }],
            "members": members,
            "profiles": [],
            "me": "did:none"
        })),
    )
    .to_json();
    menu[0]["items"]
        .as_array()
        .unwrap()
        .iter()
        .map(|i| i["label"].as_str().unwrap().to_string())
        .collect()
}

/// The assignment menu orders members `byName` too (involvementMenu.ts:104), after any holder.
#[test]
fn the_assignment_menu_sorts_like_the_browser() {
    let v = vectors();
    for s in v["sorts"].as_array().unwrap() {
        let input = strs(&s["input"]);
        assert_eq!(
            menu_labels(&input, None),
            strs(&s["sorted"]),
            "menu over {input:?}"
        );
    }
    // The holder leads; the rest keep the browser's order.
    let input = ["Zoe", "alice", "Bob", "éric"];
    let sorted = v["sorts"]
        .as_array()
        .unwrap()
        .iter()
        .find(|s| strs(&s["input"]) == input)
        .map(|s| strs(&s["sorted"]))
        .unwrap();
    let mut expected = vec!["Zoe"];
    expected.extend(sorted.into_iter().filter(|n| *n != "Zoe"));
    assert_eq!(menu_labels(&input, Some(0)), expected);
}
